test('slugify folds accents and symbols and never returns an empty id', () => {
  assert.equal(slugify('Kitchen Lamp #2'), 'kitchen_lamp_2');
  assert.equal(slugify('Café Lumière'), 'cafe_lumiere');
  assert.equal(slugify('  ---  '), 'unnamed');
});

